-- A live session is required even when a JWT has not reached its own expiry.
create or replace function private.actor_org() returns uuid language sql stable security definer set search_path='' as $$select p.organization_id from public.profiles p where p.id=auth.uid() and p.active and p.archived_at is null and exists(select 1 from auth.sessions s where s.id::text=auth.jwt()->>'session_id' and s.user_id=p.id and (s.not_after is null or s.not_after>now()))$$;
-- Closing/archiving the exam ends existing attempts without requiring missing answers.
do $patch$ declare definition text;begin
 select pg_get_functiondef('private.attempt_command(jsonb)'::regprocedure) into definition;
 definition:=replace(definition,'if a.finalized_at is null and clock_timestamp()>=a.deadline_at then',E'if a.finalized_at is null and exists(select 1 from public.exams closed_exam where closed_exam.id=a.exam_id and closed_exam.status in (\'closed\',\'archived\')) then update public.exam_attempts set deadline_at=greatest(started_at,least(deadline_at,clock_timestamp())) where id=target returning * into a;end if;\n if a.finalized_at is null and clock_timestamp()>=a.deadline_at then');
 execute definition;
end $patch$;
create or replace function public.advance_exam_schedule() returns integer language plpgsql security invoker set search_path='' as $$declare n int;item record;begin update public.exams set status=case when clock_timestamp()>=ends_at then 'closed' else 'active' end where status in ('scheduled','active') and (clock_timestamp()>=starts_at or clock_timestamp()>=ends_at);get diagnostics n=row_count;update public.exam_attempts a set deadline_at=greatest(a.started_at,least(a.deadline_at,clock_timestamp())) where a.finalized_at is null and exists(select 1 from public.exams e where e.id=a.exam_id and e.status in ('closed','archived'));for item in select id from public.exam_attempts where finalized_at is null and status in ('in_progress','disqualified') and deadline_at<=clock_timestamp() order by id for update skip locked loop perform private.attempt_finalize(item.id,'timeout');end loop;return n;end$$;
